import React from "react";
import logo from "../Assets/logo.png";

/**
 * Reusable header used in all printable forms.
 * Renders the Sakthi Auto logo on the left and the form title centered.
 * The component is deliberately simple – no navigation, no extra UI.
 * It is designed to be wrapped inside a printable container (class "printable").
 */
const FormHeader = ({ title }) => (
  <div className="grid grid-cols-12 border-b-[1.5px] border-black mb-4">
    {/* Left logo block */}
    <div className="col-span-12 sm:col-span-4 border-r-[1.5px] border-black p-2.5 flex items-center gap-3">
      <div className="w-12 h-12 flex-shrink-0 flex items-center justify-center">
        <img src={logo} alt="Sakthi Auto" className="max-h-11 max-w-full object-contain" />
      </div>
      <div className="leading-tight font-black uppercase text-[10px] tracking-tight text-gray-900">
        <div className="font-serif text-xs tracking-wider">SAKTHI</div>
        <div>AUTO COMPONENT</div>
        <div>LIMITED</div>
      </div>
    </div>
    {/* Right title block */}
    <div className="col-span-12 sm:col-span-8 p-3 flex flex-col justify-center items-center text-center bg-white">
      <h1 className="text-base sm:text-xl font-black uppercase tracking-wider text-black">
        {title}
      </h1>
    </div>
  </div>
);

export default FormHeader;
